import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Calendar, Clock, Send, CheckCircle, XCircle, Settings, Upload, FileText, Image, Key, ArrowRight, ArrowLeft } from 'lucide-react';

const SocialMediaScheduler = ({ blogContent, postingHistory, setPostingHistory, setBlogContent }) => {
  const [currentStep, setCurrentStep] = useState(1);
  const [selectedPlatforms, setSelectedPlatforms] = useState([]);
  const [scheduleDate, setScheduleDate] = useState(new Date().toISOString().split('T')[0]);
  const [scheduleTime, setScheduleTime] = useState('18:00');
  const [uploadedFile, setUploadedFile] = useState(null);
  const [generatedFromFile, setGeneratedFromFile] = useState(false);
  const [tokens, setTokens] = useState({
    facebook: '',
    twitter: '',
    linkedin: 'AQWmFzYC_NIKMAnx9ftq...',
    instagram: ''
  });

  const platforms = [
    { id: 'facebook', name: '📘 Facebook', color: '#1877F2' },
    { id: 'twitter', name: '🐦 Twitter', color: '#1DA1F2' },
    { id: 'linkedin', name: '💼 LinkedIn', color: '#0077B5' },
    { id: 'instagram', name: '📷 Instagram', color: '#E4405F' }
  ];

  const handlePlatformToggle = (platformId) => {
    setSelectedPlatforms(prev => 
      prev.includes(platformId) 
        ? prev.filter(id => id !== platformId)
        : [...prev, platformId]
    );
  };

  const handleFileUpload = async (event) => {
    const file = event.target.files[0];
    if (!file) return;

    setUploadedFile(file);

    // Simulate file processing and blog generation
    setTimeout(() => {
      const fileBasedContent = {
        title: `Insights from ${file.name.replace(/\.[^/.]+$/, "")}`,
        content: `## Document Analysis: ${file.name}\n\nBased on the uploaded document, here are the key insights and findings. This comprehensive analysis covers the main topics, trends, and actionable recommendations derived from the content.\n\n### Key Highlights\n* **Main Topic**: Extracted from document analysis\n* **Key Insights**: Important findings and data points\n* **Recommendations**: Actionable steps and strategies\n\n### Summary\nThe document provides valuable information that can be leveraged for content creation and strategic planning. These insights offer a foundation for informed decision-making and content development.`,
        hashtags: ['#DocumentAnalysis', '#Insights', '#DataDriven', '#Content', '#Strategy', '#Analysis', '#Research', '#Business'],
        cta: 'What are your thoughts on these insights? Share your perspective!',
        keywords: ['analysis', 'insights', 'document', 'research', 'strategy'],
        engagement_score: 0.82,
        platform: '📄 Document',
        wordCount: 150
      };

      setBlogContent(fileBasedContent);
      setGeneratedFromFile(true);
    }, 2000);
  };

  const saveTokens = () => {
    localStorage.setItem('socialMediaTokens', JSON.stringify(tokens));
    setCurrentStep(3);
  };

  const loadSavedTokens = () => {
    const saved = localStorage.getItem('socialMediaTokens');
    if (saved) {
      setTokens(JSON.parse(saved));
    }
  };

  const schedulePost = () => {
    if (!blogContent || selectedPlatforms.length === 0) return;

    const newPost = {
      id: Date.now(),
      title: blogContent.title,
      platforms: selectedPlatforms.map(id => platforms.find(p => p.id === id).name),
      scheduledTime: new Date(`${scheduleDate}T${scheduleTime}`),
      status: 'scheduled',
      createdAt: new Date(),
      source: generatedFromFile ? 'file' : 'manual'
    };

    setPostingHistory(prev => [...prev, newPost]);

    // Simulate posting
    setTimeout(() => {
      const results = selectedPlatforms.map(platformId => ({
        platform: platformId,
        success: Math.random() > 0.3, // 70% success rate
        message: Math.random() > 0.3 ? 'Posted successfully' : 'API error'
      }));

      setPostingHistory(prev => 
        prev.map(post => 
          post.id === newPost.id 
            ? { 
                ...post, 
                status: results.some(r => r.success) ? 'posted' : 'failed',
                results,
                postedAt: new Date()
              }
            : post
        )
      );
    }, 2000);

    setCurrentStep(1); // Reset to step 1
  };

  React.useEffect(() => {
    loadSavedTokens();
  }, []);

  const renderStep1 = () => (
    <div className="step-content">
      <h3>📄 Step 1: Content Source</h3>

      <div className="content-options">
        <div className="option-card">
          <h4>📝 Use Generated Content</h4>
          {blogContent ? (
            <div className="content-preview-mini">
              <p><strong>{blogContent.title}</strong></p>
              <p>{blogContent.content.substring(0, 100)}...</p>
              <button className="button-primary" onClick={() => setCurrentStep(2)}>
                <ArrowRight size={16} />
                Use This Content
              </button>
            </div>
          ) : (
            <p>No content generated yet. Please generate content first.</p>
          )}
        </div>

        <div className="option-card">
          <h4>📁 Upload Document/Image</h4>
          <div className="upload-area">
            <input
              type="file"
              accept=".pdf,.doc,.docx,.txt,.jpg,.jpeg,.png"
              onChange={handleFileUpload}
              className="file-input"
              id="file-upload"
            />
            <label htmlFor="file-upload" className="upload-label">
              <Upload size={24} />
              <span>Upload PDF, Document, or Image</span>
            </label>
            {uploadedFile && (
              <div className="file-info">
                <FileText size={16} />
                <span>{uploadedFile.name}</span>
                {generatedFromFile && (
                  <button className="button-secondary" onClick={() => setCurrentStep(2)}>
                    <ArrowRight size={16} />
                    Use Generated Content
                  </button>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );

  const renderStep2 = () => (
    <div className="step-content">
      <h3>🔑 Step 2: Configure API Tokens</h3>

      <div className="token-config">
        {platforms.map(platform => (
          <div key={platform.id} className="token-field">
            <label>{platform.name} API Token:</label>
            <div className="token-input-group">
              <Key size={16} />
              <input
                type="password"
                className="input-field"
                placeholder={`Enter ${platform.name} token...`}
                value={tokens[platform.id]}
                onChange={(e) => setTokens(prev => ({...prev, [platform.id]: e.target.value}))}
              />
            </div>
          </div>
        ))}

        <div className="step-actions">
          <button className="button-secondary" onClick={() => setCurrentStep(1)}>
            <ArrowLeft size={16} />
            Back
          </button>
          <button className="button-primary" onClick={saveTokens}>
            <ArrowRight size={16} />
            Save & Continue
          </button>
        </div>
      </div>
    </div>
  );

  const renderStep3 = () => (
    <div className="step-content">
      <h3>📅 Step 3: Schedule & Post</h3>

      {blogContent && (
        <div className="final-content-preview">
          <h4>📝 Content to Post:</h4>
          <div className="content-summary">
            <p><strong>{blogContent.title}</strong></p>
            <p>{blogContent.content.substring(0, 200)}...</p>
            <div className="content-meta-mini">
              <span>📝 {blogContent.wordCount || blogContent.content.split(' ').length} words</span>
              <span>🏷️ {blogContent.hashtags.length} hashtags</span>
            </div>
          </div>
        </div>
      )}

      <div className="platform-selection">
        <h4>🔗 Select Platforms:</h4>
        <div className="platforms-grid">
          {platforms.map(platform => (
            <motion.div
              key={platform.id}
              className={`platform-card ${selectedPlatforms.includes(platform.id) ? 'selected' : ''}`}
              onClick={() => handlePlatformToggle(platform.id)}
              whileHover={{ scale: 1.02 }}
            >
              <span>{platform.name}</span>
              {tokens[platform.id] ? (
                <CheckCircle size={16} className="status-icon success" />
              ) : (
                <XCircle size={16} className="status-icon error" />
              )}
            </motion.div>
          ))}
        </div>
      </div>

      <div className="schedule-settings">
        <h4>⏰ Schedule Settings:</h4>
        <div className="schedule-grid">
          <input
            type="date"
            className="input-field"
            value={scheduleDate}
            onChange={(e) => setScheduleDate(e.target.value)}
          />
          <input
            type="time"
            className="input-field"
            value={scheduleTime}
            onChange={(e) => setScheduleTime(e.target.value)}
          />
        </div>
      </div>

      <div className="step-actions">
        <button className="button-secondary" onClick={() => setCurrentStep(2)}>
          <ArrowLeft size={16} />
          Back
        </button>
        <button 
          className="button-primary"
          onClick={schedulePost}
          disabled={selectedPlatforms.length === 0}
        >
          <Send size={16} />
          Schedule Post ({selectedPlatforms.length} platforms)
        </button>
      </div>
    </div>
  );

  return (
    <div className="social-scheduler">
      <motion.div 
        className="card"
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ duration: 0.4 }}
      >
        <div className="section-header">
          <Calendar className="section-icon" />
          <h2>Dynamic Social Media Scheduler</h2>
        </div>

        <div className="step-indicator">
          {[1, 2, 3].map(step => (
            <div key={step} className={`step ${currentStep >= step ? 'active' : ''}`}>
              <span>{step}</span>
            </div>
          ))}
        </div>

        {currentStep === 1 && renderStep1()}
        {currentStep === 2 && renderStep2()}
        {currentStep === 3 && renderStep3()}
      </motion.div>

